from pathlib import Path
import json
r=Path(__file__).resolve().parent
changes=json.loads('{"server/index.mjs": [["   if(p===\'/bootstrap.js\'){const result=await stateFor(s);", "   if([\'/olivia-preview\',\'/olivia-preview-bootstrap.js\'].includes(p)){\\n    if(s.user_id!==\'u0\')fail(403,\'This preview is only available to Steven.\');\\n    if(req.method!==\'GET\')fail(405,\'This preview is read-only.\');\\n    if(p===\'/olivia-preview-bootstrap.js\'){const result=await stateFor({...s,user_id:\'u2\'});result.csrf=null;result.preview=true;res.writeHead(200,{\'Content-Type\':\'text/javascript\'});return res.end(\'window.TL_BOOT=\'+JSON.stringify(result).replace(/</g,\'\\\\\\\\u003c\')+\';\');}\\n    const html=readFileSync(path.join(ROOT,\'site/index.html\'),\'utf8\').replace(\'src=\\"bootstrap.js\\"\',\'src=\\"olivia-preview-bootstrap.js\\"\').replace(/src=\\"remote\\\\.js[^\\\\\\"]*\\"/,\'src=\\"olivia-preview.js\\"\');\\n    res.writeHead(200,{\'Content-Type\':\'text/html; charset=utf-8\'});return res.end(html);\\n   }\\n   if(p===\'/bootstrap.js\'){const result=await stateFor(s);"], ["Location:p===\'/voice-test\'||p===\'/voice-test.html\'?\'/login?next=%2Fvoice-test\':\'/login\'", "Location:p===\'/olivia-preview\'?\'/login?next=%2Folivia-preview\':p===\'/voice-test\'||p===\'/voice-test.html\'?\'/login?next=%2Fvoice-test\':\'/login\'"]], "site/login.js": [["location.href=new URLSearchParams(location.search).get(\'next\')===\'/voice-test\'?\'/voice-test\':\'/\';", "const next=new URLSearchParams(location.search).get(\'next\');location.href=[\'/voice-test\',\'/olivia-preview\'].includes(next)?next:\'/\';"]]}')
for name,edits in changes.items():
 p=r/name
 s=p.read_text()
 for before,after in edits:
  if s.count(before)!=1: raise SystemExit(name+": unexpected preview source")
  s=s.replace(before,after,1)
 p.write_text(s)
(r/"site/olivia-preview.js").write_text('/* Owner-only preview. Scoped live data, no staff session or save transport. */\n(function(){\n\'use strict\';\nif(!window.TL_BOOT?.preview)return;\nconst TL=window.TL,boot=window.TL_BOOT;\nconst message=\'You are previewing Olivia’s view. Changes are disabled. Return to your account to edit.\';\nfunction blocked(){throw new Error(message);}\nfor(const op of [\'createLead\',\'updateLead\',\'setStage\',\'assign\',\'setDoc\',\'addActivity\',\'attachFile\',\'setTemp\',\'closeLead\',\'reopenLead\',\'addTask\',\'completeReminder\',\'snoozeReminder\',\'resolveTask\',\'setBuildingAccess\',\'setCountyStep\',\'setReferralProgress\',\'saveReferral\',\'addReferrer\',\'addFollowupContact\',\'save\',\'reset\',\'simulateSend\',\'importJson\',\'uploadFile\'])TL[op]=blocked;\nTL.sweep=()=>false;TL.flush=async()=>{};\nwindow.TLRemote={request:async()=>blocked(),refresh:()=>location.reload(),importLeads:async()=>blocked(),enableNotifications:async()=>blocked(),disableNotifications:async()=>blocked(),retry:()=>{},pending:0,broken:false};\n// Reject every network mutation, including intake, invitations and sign-out.\nconst originalFetch=window.fetch.bind(window);window.fetch=function(input,options={}){const method=(options.method||(input instanceof Request?input.method:\'GET\')).toUpperCase();if(![\'GET\',\'HEAD\'].includes(method))return Promise.reject(new Error(message));return originalFetch(input,options);};\nwindow.addEventListener(\'DOMContentLoaded\',()=>{\n document.getElementById(\'userSel\').disabled=true;\n const banner=document.querySelector(\'.demo-banner\');banner.hidden=false;banner.textContent=\'Olivia’s live view · Preview only · Changes are disabled\';\n const links=document.createElement(\'div\');links.className=\'btnrow\';\n for(const [label,url]of [[\'Return to my account\',\'/\'],[\'Refresh Olivia’s view\',\'/olivia-preview\'+location.hash]]){const a=document.createElement(\'a\');a.className=\'btn small ghost\';a.textContent=label;a.href=url;links.append(a);}banner.append(links);\n document.querySelector(\'[data-act="reset"]\')?.remove();\n});\n})();\n')

(r/"test/olivia-preview.test.mjs").write_text('import test from \'node:test\';import assert from \'node:assert/strict\';import {createHmac} from \'node:crypto\';import {mkdtempSync,rmSync,readFileSync} from \'node:fs\';import {tmpdir} from \'node:os\';import path from \'node:path\';import vm from \'node:vm\';import {createApplication} from \'../server/index.mjs\';import {initialState,execute,scoped} from \'../server/engine.mjs\';\ntest(\'owner preview renders the existing app with precisely Olivia scoped data and keeps the owner session intact\',async()=>{const dir=mkdtempSync(path.join(tmpdir(),\'olivia-preview-\')),secret=\'preview-secret\',app=await createApplication({schedule:false,env:{NODE_ENV:\'test\',APP_MODE:\'live\',PHI_APPROVED:\'true\',DATABASE_URL:\'\',SQLITE_PATH:path.join(dir,\'db\'),SESSION_SECRET:secret,DELEGATE_ACCESS_HASH:\'a\'.repeat(64),DELEGATE_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString(),VIEWER_ACCESS_HASH:\'b\'.repeat(64),VIEWER_ACCESS_EXPIRES_AT:\'never\',VIEWER_EMAIL:\'zach@tharongroup.com\',ZACH_LEAD_EDIT_ACCESS:\'true\'}});await new Promise(r=>app.server.listen(0,\'127.0.0.1\',r));const origin=\'http://127.0.0.1:\'+app.server.address().port;try{let state=initialState(false);for(const [id,rep,building]of [[\'L_preview_olivia\',\'u2\',\'riverside\'],[\'L_preview_morgan\',\'u1\',\'sierra\'],[\'L_preview_gaby\',\'u3\',\'hallmark\'],[\'L_preview_other\',\'u0\',\'riverside\']])state=execute(state,\'u0\',{op:\'createLead\',createdId:id,args:[{first:\'Synthetic\',last:id,rep,building,payer:\'Private pay\'}]});await app.store.query(\'UPDATE app_state SET data=$1 WHERE id=$2\',[JSON.stringify(state),\'main\']);for(const uid of [\'u0\',\'u1\',\'u2\',\'u3\',\'u4\',\'u6\'])await app.store.query(\'INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)\',[createHmac(\'sha256\',secret).update(uid).digest(\'hex\'),uid,Date.now()+60000,(uid===\'u4\'?\'a\'.repeat(64)+\'.\':uid===\'u6\'?\'b\'.repeat(64)+\'.\':\'\')+\'csrf\']);const get=(p,uid=\'u0\',method=\'GET\')=>fetch(origin+p,{redirect:\'manual\',method,headers:uid?{Cookie:\'tl_session=\'+uid}:{}});const unauth=await get(\'/olivia-preview\',null);assert.equal(unauth.status,302);assert.equal(unauth.headers.get(\'location\'),\'/login?next=%2Folivia-preview\');for(const uid of [\'u1\',\'u2\',\'u3\',\'u4\',\'u6\'])for(const p of [\'/olivia-preview\',\'/olivia-preview-bootstrap.js\'])assert.equal((await get(p,uid)).status,403);for(const p of [\'/olivia-preview\',\'/olivia-preview-bootstrap.js\'])assert.equal((await get(p,\'u0\',\'POST\')).status,405);const html=await (await get(\'/olivia-preview\')).text();assert.ok(html.includes(\'src="olivia-preview-bootstrap.js"\'));assert.ok(html.includes(\'src="olivia-preview.js"\'));assert.ok(!html.includes(\'src="remote.js\'));assert.ok(html.includes(\'src="app.js\'));const response=await get(\'/olivia-preview-bootstrap.js\');assert.equal(response.headers.get(\'cache-control\'),\'no-store\');const ctx={window:{}};vm.createContext(ctx);vm.runInContext(await response.text(),ctx);const boot=JSON.parse(JSON.stringify(ctx.window.TL_BOOT));assert.equal(boot.preview,true);assert.equal(boot.csrf,null);assert.deepEqual(boot.state,JSON.parse(JSON.stringify(scoped(state,\'u2\'))));assert.equal((await (await get(\'/api/state\')).json()).state.me,\'u0\');assert.deepEqual(JSON.parse((await app.store.query(\'SELECT data FROM app_state WHERE id=$1\',[\'main\']))[0].data),state);}finally{await app.close();rmSync(dir,{recursive:true,force:true});}});\ntest(\'preview transport blocks app mutations before they change local data and rejects network writes\',async()=>{const source=readFileSync(new URL(\'../site/olivia-preview.js\',import.meta.url),\'utf8\');let saved=0,requests=0;const TL={saveReferral:()=>saved++,save:()=>saved++,createLead:()=>saved++},w={TL_BOOT:{preview:true},TL,fetch:async()=>{requests++;return \'ok\';},addEventListener:()=>{}};const ctx={window:w,Request,location:{reload:()=>{}},console};vm.createContext(ctx);vm.runInContext(source,ctx);for(const op of [\'saveReferral\',\'save\',\'createLead\',\'uploadFile\',\'setCountyStep\'])assert.throws(()=>TL[op](),/previewing Olivia/);assert.equal(saved,0);for(const method of [\'POST\',\'PATCH\',\'PUT\',\'DELETE\'])await assert.rejects(w.fetch(\'/api/commands\',{method}),/previewing Olivia/);await assert.rejects(w.fetch(new Request(\'https://example.com/api/commands\',{method:\'POST\'})),/previewing Olivia/);assert.equal(requests,0);assert.equal(await w.fetch(\'/api/files/example\'),\'ok\');assert.equal(requests,1);assert.equal(w.TLRemote.pending,0);await assert.rejects(w.TLRemote.request(\'/api/commands\'),/previewing Olivia/);});\n')
